const (
	defaultTrashDir         = ".opensync-trash"
	defaultTrashRetention   = 30
	maxTrashRetentionDays   = 3650
	emptySrcDirStagePrefix  = ".opensync-rmdir-"
)

var conflictBackupNamePattern = regexp.MustCompile(`^.+?\.conflict-\d{8}-\d{6}(?:\.[^./]+)?$`)

// isConflictBackupName reports whether fileName matches the timestamped backup
// name generated by conflictBackupName for conflictPolicy=2 (keep both).
func isConflictBackupName(fileName string) bool {
	if fileName == "" || strings.HasSuffix(fileName, "/") || strings.ContainsAny(fileName, "/\\") {
		return false
	}
	return conflictBackupNamePattern.MatchString(fileName)
}

func randomHexToken(numBytes int) string {
	buf := make([]byte, numBytes)
	if _, err := rand.Read(buf); err != nil {
		return fmt.Sprintf("%x", time.Now().UnixNano())
	}
	return hex.EncodeToString(buf)
}

func isAlistAlreadyExistsError(err error) bool {
	if err == nil {
		return false
	}
	lower := strings.ToLower(err.Error())
	return strings.Contains(lower, "exist") || strings.Contains(lower, "已存在")
}

// normalizeTrashDir validates and normalizes a job's relative trash directory name.
func normalizeTrashDir(raw string) (string, error) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return defaultTrashDir, nil
	}
	trimmed = strings.TrimSuffix(trimmed, "/")
	if trimmed == "" ||
		strings.HasPrefix(trimmed, "/") ||
		strings.Contains(trimmed, "//") ||
		strings.ContainsAny(trimmed, `\*?[]{}!`) ||
		containsControl(trimmed) {
		return "", publicError(msg.T(msg.TrashDirInvalid))
	}
	for _, seg := range strings.Split(trimmed, "/") {
		if seg == "" || seg == "." || seg == ".." {
			return "", publicError(msg.T(msg.TrashDirInvalid))
		}
	}
	return trimmed, nil
}

func trashEnabled(job map[string]interface{}) bool {
	return job != nil && util.ToInt(job["trashEnable"]) == 1
}

func jobTrashDir(job map[string]interface{}) string {
	if job == nil {
		return defaultTrashDir
	}
	dir, err := normalizeTrashDir(util.StringValue(job["trashDir"]))
	if err != nil || dir == "" {
		return defaultTrashDir
	}
	return dir
}

func jobTrashRetentionDays(job map[string]interface{}) int {
	if job == nil {
		return defaultTrashRetention
	}
	raw, ok := job["trashRetentionDays"]
	if !ok || raw == nil {
		return defaultTrashRetention
	}
	days := util.ToInt(raw)
	if days < 0 {
		return 0
	}
	if days > maxTrashRetentionDays {
		return maxTrashRetentionDays
	}
	return days
}

// conflictBackupName builds a timestamped rename target for conflictPolicy=2 (keep both).
func conflictBackupName(fileName string, now time.Time) string {
	suffix := ".conflict-" + now.In(schedulerLocation()).Format("20060102-150405")
	ext := path.Ext(fileName)
	base := strings.TrimSuffix(fileName, ext)
	// Preserve dot-files like ".gitignore" where ext == fileName.
	if ext == "" || base == "" {
		return fileName + suffix
	}
	return base + suffix + ext
}

type remoteDirCreator interface {
	MkdirContext(context.Context, string, int) error
}

type trashDirState struct {
	done chan struct{}
	err  error
}

func ensureRemoteDirHierarchyWith(baseRoot, relPath string, ensureDir func(string) error) error {
	baseRoot = normalizeDirPath(baseRoot)
	relPath = strings.Trim(relPath, "/")
	if relPath == "" {
		return nil
	}
	cur := strings.TrimRight(baseRoot, "/")
	for _, seg := range strings.Split(relPath, "/") {
		if seg == "" {
			continue
		}
		cur = cur + "/" + seg
		dirKey := cur + "/"
		if err := ensureDir(dirKey); err != nil {
			return err
		}
	}
	return nil
}

func ensureRemoteDirHierarchy(ctx context.Context, client remoteDirCreator, baseRoot, relPath string, scanInterval int, created map[string]struct{}, markCreated func(string) bool) error {
	return ensureRemoteDirHierarchyWith(baseRoot, relPath, func(dirKey string) error {
		if markCreated != nil {
			if !markCreated(dirKey) {
				return nil
			}
		} else if created != nil {
			if _, ok := created[dirKey]; ok {
				return nil
			}
		}
		if err := client.MkdirContext(ctx, dirKey, scanInterval); err != nil {
			if !isAlistAlreadyExistsError(err) {
				return err
			}
		}
		if created != nil {
			created[dirKey] = struct{}{}
		}
		return nil
	})
}

// waitForAlistRemoteMove waits for an asynchronous /api/fs/move task to finish
// when OpenList/AList returns a task ID. If the task record disappears (404),
// itemDir/cleanName is probed to verify the source file actually moved before
// reporting success.
func waitForAlistRemoteMove(ctx context.Context, client copyItemClient, taskID, itemDir, cleanName string) error {
	if taskID == "" {
		return nil
	}
	ticker := time.NewTicker(400 * time.Millisecond)
	defer ticker.Stop()
	deadline := time.NewTimer(5 * time.Minute)
	defer deadline.Stop()
	for {
		info, err := client.TaskInfoContext(ctx, taskID, taskItemTypeMove)
		if err != nil {
			if isAlistObjectNotFound(err) {
				exists, statErr := client.FileExistsContext(ctx, itemDir, cleanName)
				if statErr == nil && !exists {
					return nil
				}
				if statErr != nil {
					return fmt.Errorf("trash move task %s vanished and source probe failed: %w", taskID, statErr)
				}
				return fmt.Errorf("trash move task %s vanished while %q still exists", taskID, cleanName)
			}
			return err
		}
		state := util.ToInt(info["state"])
		switch state {
		case 2: // succeeded
			return nil
		case 3, 4, 7: // cancelled / errored / failed
			errMsg := util.StringValue(info["error"])
			if errMsg == "" {
				errMsg = fmt.Sprintf("trash move task %s failed (state=%d)", taskID, state)
			}
			return errors.New(errMsg)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-deadline.C:
			return fmt.Errorf("trash move task %s timed out", taskID)
		case <-ticker.C:
		}
	}
}

func (jt *JobTask) ensureTrashDirSegment(ctx context.Context, dirKey string, scanInterval int) error {
	jt.trashDirMu.Lock()
	if jt.trashDirReady == nil {
		jt.trashDirReady = make(map[string]struct{})
	}
	if _, ready := jt.trashDirReady[dirKey]; ready {
		jt.trashDirMu.Unlock()
		return nil
	}
	if jt.trashDirBusy == nil {
		jt.trashDirBusy = make(map[string]*trashDirState)
	}
	if state, busy := jt.trashDirBusy[dirKey]; busy {
		jt.trashDirMu.Unlock()
		select {
		case <-state.done:
			return state.err
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	state := &trashDirState{done: make(chan struct{})}
	jt.trashDirBusy[dirKey] = state
	jt.trashDirMu.Unlock()

	err := jt.AlistClient.MkdirContext(ctx, dirKey, scanInterval)
	if err != nil && isAlistAlreadyExistsError(err) {
		err = nil
	}

	jt.trashDirMu.Lock()
	delete(jt.trashDirBusy, dirKey)
	if err == nil {
		jt.trashDirReady[dirKey] = struct{}{}
	}
	state.err = err
	close(state.done)
	jt.trashDirMu.Unlock()
	return err
}

func (jt *JobTask) invalidateTrashDirHierarchy(baseRoot, relPath string) {
	baseRoot = normalizeDirPath(baseRoot)
	relPath = strings.Trim(relPath, "/")
	if relPath == "" {
		return
	}
	jt.trashDirMu.Lock()
	defer jt.trashDirMu.Unlock()
	if jt.trashDirReady == nil {
		return
	}
	cur := strings.TrimRight(baseRoot, "/")
	for _, seg := range strings.Split(relPath, "/") {
		if seg == "" {
			continue
		}
		cur = cur + "/" + seg
		delete(jt.trashDirReady, cur+"/")
	}
}

func (jt *JobTask) nextTrashVersionBucket(now time.Time, dateBucket, relDir, cleanName string) string {
	jt.trashDirMu.Lock()
	defer jt.trashDirMu.Unlock()
	if jt.trashRunBucket == "" {
		timePart := now.In(schedulerLocation()).Format("150405")
		token := randomHexToken(4)
		if jt.TaskID > 0 {
			jt.trashRunBucket = fmt.Sprintf("%s-t%d-%s", timePart, jt.TaskID, token)
		} else {
			jt.trashRunBucket = fmt.Sprintf("%s-%s", timePart, token)
		}
	}
	if jt.trashItemCounts == nil {
		jt.trashItemCounts = make(map[string]int)
	}
	key := dateBucket + "/" + relDir + "/" + cleanName
	count := jt.trashItemCounts[key] + 1
	jt.trashItemCounts[key] = count
	if count == 1 {
		return jt.trashRunBucket
	}
	return fmt.Sprintf("%s-%d", jt.trashRunBucket, count)
}

// moveItemToTrash moves a destination file or directory into
// <dstRoot>/<trashDir>/<YYYY-MM-DD>/<versionBucket>/<relDir>. It NEVER falls
// back to hard delete and never overwrites an existing trashed version.
func (jt *JobTask) moveItemToTrash(dstRoot, itemDir, itemName string) error {
	if jt.AlistClient == nil {
		return errors.New("alist client unavailable for trash move")
	}
	dstRoot = normalizeDirPath(dstRoot)
	itemDir = normalizeDirPath(itemDir)
	cleanName := strings.TrimSuffix(itemName, "/")
	if !isSafeDeleteTargetName(cleanName) {
		return errors.New(unsafeDeleteTargetMessage(itemDir, itemName))
	}
	trashDir := jobTrashDir(jt.Job)
	now := time.Now()
	dateBucket := now.In(schedulerLocation()).Format("2006-01-02")
	relDir := ""
	if strings.HasPrefix(itemDir, dstRoot) {
		relDir = strings.Trim(strings.TrimPrefix(itemDir, dstRoot), "/")
	}
	versionBucket := jt.nextTrashVersionBucket(now, dateBucket, relDir, cleanName)
	relTarget := trashDir + "/" + dateBucket + "/" + versionBucket
	if relDir != "" {
		relTarget += "/" + relDir
	}
	scanIntervalT := util.ToInt(jt.Job["scanIntervalT"])
	if err := ensureRemoteDirHierarchyWith(dstRoot, relTarget, func(dirKey string) error {
		return jt.ensureTrashDirSegment(jt.context(), dirKey, scanIntervalT)
	}); err != nil {
		return fmt.Errorf("create trash directory %q: %w", dstRoot+relTarget+"/", err)
	}
	targetDir := normalizeDirPath(dstRoot + relTarget)
	taskID, err := jt.AlistClient.MoveFileNoOverwriteContext(jt.context(), itemDir, targetDir, cleanName)
	if err != nil {
		if isAlistObjectNotFound(err) {
			// /api/fs/move returns "object not found" both when itemDir/cleanName
			// is absent AND when targetDir does not exist remotely. Only treat it
			// as already gone after verifying the source object is absent.
			exists, statErr := jt.AlistClient.FileExistsContext(jt.context(), itemDir, cleanName)
			if statErr == nil && !exists {
				return nil
			}
			jt.invalidateTrashDirHierarchy(dstRoot, relTarget)
		}
		return fmt.Errorf("move %q to trash %q: %w", cleanName, targetDir, err)
	}
	if taskID != "" {
		if err := waitForAlistRemoteMove(jt.context(), jt.AlistClient, taskID, itemDir, cleanName); err != nil {
			return fmt.Errorf("wait trash move %q: %w", cleanName, err)
		}
	}
	return nil
}

// cleanupExpiredTrash removes date buckets under <dstRoot>/<trashDir>/ older
// than retentionDays. Errors are logged and do not fail an otherwise clean sync.
func (jt *JobTask) cleanupExpiredTrash() {
	if !trashEnabled(jt.Job) || jt.AlistClient == nil {
		return
	}
	retentionDays := jobTrashRetentionDays(jt.Job)
	if retentionDays <= 0 {
		return
	}
	if jt.isBreak() || jt.context().Err() != nil {
		return
	}
	trashDir := jobTrashDir(jt.Job)
	scanIntervalT := util.ToInt(jt.Job["scanIntervalT"])
	today := time.Now().In(schedulerLocation())
	cutoffDate := time.Date(today.Year(), today.Month(), today.Day(), 0, 0, 0, 0, schedulerLocation()).AddDate(0, 0, -retentionDays)

	dstRoots := make(map[string]struct{})
	for _, work := range jt.configuredScanWorks(parsePathList(jt.Job["dstPath"])) {
		dstRoots[normalizeDirPath(work.DstRootPath)] = struct{}{}
	}
	for dstRoot := range dstRoots {
		if jt.isBreak() || jt.context().Err() != nil {
			return
		}
		trashRoot := normalizeDirPath(dstRoot + trashDir)
		entries, err := jt.AlistClient.FileListApiContext(jt.context(), trashRoot, 0, scanIntervalT)
		if err != nil {
			if !isAlistObjectNotFound(err) {
				log.Printf("Task %d trash cleanup list %q failed: %v", jt.TaskID, trashRoot, err)
			}
			continue
		}
		for name := range entries {
			if !strings.HasSuffix(name, "/") {
				continue
			}
			dirName := strings.TrimSuffix(name, "/")
			bucketTime, parseErr := time.ParseInLocation("2006-01-02", dirName, schedulerLocation())
			if parseErr != nil {
				continue
			}
			if bucketTime.Before(cutoffDate) {
				if err := jt.AlistClient.DeleteFileContext(jt.context(), trashRoot, []string{dirName}, scanIntervalT); err != nil {
					log.Printf("Task %d failed to purge expired trash bucket %q: %v", jt.TaskID, trashRoot+dirName, err)
				} else {
					log.Printf("Task %d purged expired trash bucket %q", jt.TaskID, trashRoot+dirName)
				}
			}
		}
	}
}

// recordMoveSrcSubdir tracks a visited source subdirectory during move mode
// so cleanupEmptyMoveSrcDirs can remove empty subdirectories deepest-first.
func (jt *JobTask) recordMoveSrcSubdir(dirPath, rootPath string) {
	if util.ToInt(jt.Job["method"]) != 2 || util.ToInt(jt.Job["deleteEmptySrcDirs"]) != 1 {
		return
	}
	dirPath = normalizeDirPath(dirPath)
	rootPath = normalizeDirPath(rootPath)
	if dirPath == "" || rootPath == "" || dirPath == rootPath || !strings.HasPrefix(dirPath, rootPath) {
		return
	}
	jt.moveSrcDirMu.Lock()
	if jt.moveSrcSubdirs == nil {
		jt.moveSrcSubdirs = make(map[string]string)
	}
	jt.moveSrcSubdirs[dirPath] = rootPath
	jt.moveSrcDirMu.Unlock()
}

func (jt *JobTask) hasAnyFailedItem() bool {
	jt.FinishMu.Lock()
	defer jt.FinishMu.Unlock()
	if jt.FinishedCounts[taskStatusFailed] > 0 || jt.FinishedCounts[taskStatusSystemFailed] > 0 {
		return true
	}
	for s, count := range jt.FinishedCounts {
		if count > 0 && isOtherTaskStatus(s) {
			return true
		}
	}
	return false
}

// cleanupEmptyMoveSrcDirs removes empty source subdirectories deepest-first
// after a clean move run. Never removes any configured source root directory.
func (jt *JobTask) cleanupEmptyMoveSrcDirs() {
	if util.ToInt(jt.Job["method"]) != 2 || util.ToInt(jt.Job["deleteEmptySrcDirs"]) != 1 {
		return
	}
	if jt.isBreak() || jt.context().Err() != nil || jt.AlistClient == nil || jt.hasAnyFailedItem() {
		return
	}

	jt.moveSrcDirMu.Lock()
	if len(jt.moveSrcSubdirs) == 0 {
		jt.moveSrcDirMu.Unlock()
		return
	}
	dirs := make([]string, 0, len(jt.moveSrcSubdirs))
	roots := make(map[string]string, len(jt.moveSrcSubdirs))
	for dir, root := range jt.moveSrcSubdirs {
		dirs = append(dirs, dir)
		roots[dir] = root
	}
	jt.moveSrcDirMu.Unlock()

	// Deepest-first order so emptying a nested folder lets its parent become empty too.
	sort.Slice(dirs, func(i, j int) bool {
		di := strings.Count(dirs[i], "/")
		dj := strings.Count(dirs[j], "/")
		if di != dj {
			return di > dj
		}
		return dirs[i] > dirs[j]
	})

	scanIntervalS := util.ToInt(jt.Job["scanIntervalS"])
	for _, dir := range dirs {
		if jt.isBreak() || jt.context().Err() != nil {
			return
		}
		root := roots[dir]
		if dir == root || !strings.HasPrefix(dir, root) {
			continue
		}
		entries, err := jt.AlistClient.FileListApiContext(jt.context(), dir, 0, scanIntervalS)
		if err != nil {
			if !isAlistObjectNotFound(err) {
				log.Printf("Task %d empty-src-dir check failed for %q: %v", jt.TaskID, dir, err)
			}
			continue
		}
		if len(entries) > 0 {
			continue
		}
		clean := strings.TrimRight(dir, "/")
		parent := normalizeDirPath(path.Dir(clean))
		base := path.Base(clean)
		if !isSafeDeleteTargetName(base) || !strings.HasPrefix(parent, root) || strings.HasPrefix(base, emptySrcDirStagePrefix) {
			continue
		}
		// Never issue a recursive /api/fs/remove directly on the live source
		// directory name: a file written into dir between list and remove would
		// be destroyed along with the directory. Quarantine dir under a unique
		// hidden name first, re-verify it is empty on a fresh listing, and
		// restore it if anything arrived before the rename.
		stageName := fmt.Sprintf("%s%d-%s", emptySrcDirStagePrefix, jt.TaskID, randomHexToken(6))
		if err := jt.AlistClient.RenameFileContext(jt.context(), clean, stageName, scanIntervalS); err != nil {
			if !isAlistObjectNotFound(err) {
				log.Printf("Task %d empty-src-dir quarantine rename skipped for %q: %v", jt.TaskID, dir, err)
			}
			continue
		}
		stageDir := parent + stageName + "/"
		stageEntries, stageErr := jt.AlistClient.FileListApiContext(jt.context(), stageDir, 0, scanIntervalS)
		if stageErr != nil {
			if isAlistObjectNotFound(stageErr) {
				continue
			}
			log.Printf("Task %d empty-src-dir recheck failed for quarantined %q (original %q): %v; restoring", jt.TaskID, stageDir, dir, stageErr)
			jt.restoreQuarantinedSrcDir(parent, stageName, base, nil, scanIntervalS)
			continue
		}
		if len(stageEntries) > 0 {
			log.Printf("Task %d empty-src-dir %q received %d new entries before removal; restoring without deleting", jt.TaskID, dir, len(stageEntries))
			jt.restoreQuarantinedSrcDir(parent, stageName, base, stageEntries, scanIntervalS)
			continue
		}
		if jt.isBreak() || jt.context().Err() != nil {
			jt.restoreQuarantinedSrcDir(parent, stageName, base, nil, scanIntervalS)
			return
		}
		delErr := jt.AlistClient.DeleteFileContext(jt.context(), parent, []string{stageName}, scanIntervalS)
		status := taskStatusSuccess
		var errMsg *string
		if delErr != nil {
			status = taskStatusFailed
			s := delErr.Error()
			errMsg = &s
		}
		jt.DelHook(parent, base+"/", nil, status, errMsg, taskItemPath, time.Now().Unix())
	}
}

func (jt *JobTask) restoreQuarantinedSrcDir(parent, stageName, originalBase string, entries FileListResult, scanInterval int) {
	ctx, cancel := jt.cleanupContext()
	defer cancel()
	stagePath := strings.TrimRight(parent, "/") + "/" + stageName
	if err := jt.AlistClient.RenameFileContext(ctx, stagePath, originalBase, scanInterval); err == nil {
		return
	}
	// Another writer already recreated originalBase; move any newly arrived
	// entries back into it without overwriting, and only remove stageName once
	// verified empty.
	if len(entries) == 0 {
		return
	}
	stageDir := parent + stageName + "/"
	targetDir := parent + originalBase + "/"
	allMoved := true
	for name := range entries {
		cleanEntry := strings.TrimSuffix(name, "/")
		if !isSafeDeleteTargetName(cleanEntry) {
			allMoved = false
			continue
		}
		taskID, err := jt.AlistClient.MoveFileNoOverwriteContext(ctx, stageDir, targetDir, cleanEntry)
		if err != nil {
			log.Printf("Task %d failed to restore %q from %q to %q: %v", jt.TaskID, cleanEntry, stageDir, targetDir, err)
			allMoved = false
			continue
		}
		if taskID != "" {
			if err := waitForAlistRemoteMove(ctx, jt.AlistClient, taskID, stageDir, cleanEntry); err != nil {
				log.Printf("Task %d failed waiting restore of %q from %q to %q: %v", jt.TaskID, cleanEntry, stageDir, targetDir, err)
				allMoved = false
			}
		}
	}
	if !allMoved {
		return
	}
	remaining, err := jt.AlistClient.FileListApiContext(ctx, stageDir, 0, scanInterval)
	if err == nil && len(remaining) == 0 {
		_ = jt.AlistClient.DeleteFileContext(ctx, parent, []string{stageName}, scanInterval)
	}
}
